local R = require "core.lib.rathena"

return function(player, conversation, npc, ...)
  local npc_name = ""
  local args = table.pack(...)
  npc_name = R.text(R.arg(args, 0))
  conversation:say(npc_name, "Welcome to", R.arg(args, 1) .. ".", "How may I help you?")
  conversation:wait_for_next()
  do
    local value_1 = conversation:choose("Save", "Take a Rest -> 5000 zeny", "Cancel")
    if value_1 == 1 then goto case_3
    elseif value_1 == 2 then goto case_4
    elseif value_1 == 3 then goto case_5
    end
    goto switch_end_2
    ::case_3::
    conversation:say(npc_name, "Your respawn point", "has been saved.", "Thank you,", "please come again.")
    player:set_save_point(R.arg(args, 2), (R.arg(args, 3) or 0), (R.arg(args, 4) or 0))
    R.stop()
    ::case_4::
    conversation:say(npc_name)
    if (player.zeny < 5000) then
      conversation:say("I'm sorry, but the service charge is 5,000 zeny. Please make sure that you have enough money to check in next time, okay?")
      R.stop()
    end
    conversation:say("Thank you.", "I hope you", "enjoy your rest~")
    conversation:close()
    player:pay_zeny(5000)
    player:heal_percent { hp = 100, sp = 100 }
    do return end
    ::case_5::
    R.stop()
    ::switch_end_2::
  end
end
